const replacementsByFile = {};

problems.forEach(p => {
  if (!replacementsByFile[p.path]) {
    replacementsByFile[p.path] = [];
  }
  
  const matchClass = p.message.match(/The class \`(.*?)\` can be written as \`(.*?)\`/);
  if (matchClass) {
    replacementsByFile[p.path].push({ from: matchClass[1], to: matchClass[2] });
  } else if (p.message.includes("applies the same CSS properties as")) {
     const matchRedundant = p.message.match(/'(.*?)' applies the same CSS properties as '(.*?)'/);
     // Usually not safe to automatically remove if it breaks layout, but in Hero min-h-[100svh] min-h-screen it's just min-h
     // We will skip redundant ones to ensure no UI changes as the user requested ("don't change my UI")
  }
});

let updatedCount = 0;
let fileCount = 0;

for (const [path, replacements] of Object.entries(replacementsByFile)) {
  if (!fs.existsSync(path)) {
     console.log('File not found: ' + path);
     continue;
  }
  if (replacements.length === 0) continue;
  
  let content = fs.readFileSync(path, 'utf8');
  let originalContent = content;
  
  replacements.forEach(r => {
    const escapedFrom = r.from.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');
    // We only replace if surrounded by whitespace, quotes, or backticks
    const regex = new RegExp(`(?<=[\\\\s"\'\\\`])` + escapedFrom + `(?=[\\\\s"\'\\\`])`, 'g');
    content = content.replace(regex, r.to);
  });
  
  if (content !== originalContent) {
     fs.writeFileSync(path, content, 'utf8');
     fileCount++;
     updatedCount += replacements.length;
  }
}

console.log(`Successfully updated ${updatedCount} classes in ${fileCount} files.`);
